from datetime import datetime, timezone

# service -> (attempts, backoff cap, longest accepted Retry-After)
PROFILES = {
    "catalog": (6, 8, 30),
    "ledger": (8, 3, 60),
    "payments": (3, 1, 30),
    "inventory": (7, 4, 90),
    "auth": (6, 6, 20),
    "ledger-export": (4, 8, 10),
    "reports": (9, 5, 120),
    "search": (10, 12, 45),
    "shipping": (8, 3, 40),
    "media": (5, 8, 15),
}
DEFAULTS = (5, 8, 30)
IDEMPOTENT = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
RETRYABLE = {429, 502, 503, 504}
_MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
_DATE = re.compile(
    r"(Mon|Tue|Wed|Thu|Fri|Sat|Sun), (\\d{2}) (" + "|".join(_MONTHS)
    + r") (\\d{4}) (\\d{2}):(\\d{2}):(\\d{2}) GMT"
)


def _get(headers, name):
    for k, v in (headers or {}).items():
        if k.lower() == name:
            return v
    return None


def _retry_after(value, now):
    if value is None:
        return None
    value = value.strip()
    if re.fullmatch(r"[0-9]+", value):
        return float(int(value))
    m = _DATE.fullmatch(value)
    if not m:
        return None
    try:
        dt = datetime(int(m[4]), _MONTHS.index(m[3]) + 1, int(m[2]),
                      int(m[5]), int(m[6]), int(m[7]), tzinfo=timezone.utc)
    except ValueError:
        return None
    return max(0.0, (dt - now).total_seconds())
''')
